// Capture agent service — WebSocket server on 127.0.0.1:8766.
//
// The side panel connects here while a capture is pending, sends an `ask`
// (capture tree + question), streams the agent's reasoning back, and on settle
// receives { sessionId, sessionFile, model, cost } so it can stash an `agent`
// envelope on the pending capture before Save.
//
// Protocol (JSON messages):
//   panel → service: { type:"ask", captureId, tree, messages?, prompt }
//                    { type:"follow_up", captureId, prompt }
//                    { type:"abort", captureId }
//   service → panel: { type:"ready" }
//                    { type:"delta", captureId, text }
//                    { type:"tool", captureId, tool, arg }
//                    { type:"settled", captureId, sessionId, sessionFile, model, cost }
//                    { type:"error", captureId, message }
//
// Env:
//   AGENT_PORT        WebSocket port (default 8766)
//   AGENT_DATA_DIR    evidence root (default ../server/data under this repo)
//   AGENT_MOCK=1      stub mode: returns synthetic deltas + a settled event
//                     without hitting OpenRouter (used for tests/smoke).
//   OPENROUTER_API_KEY  required in real mode; never ships in the browser.

import http from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { WebSocketServer, WebSocket } from "ws";

import { CaptureAgent } from "./agent.js";
import { makeSystemPrompt } from "./agent.js";
import { costOfMessages, currentModelOf, newSessionId, persistSession } from "./persist.js";

const ROOT = path.dirname(fileURLToPath(import.meta.url));
export const DEFAULT_DATA_DIR = path.resolve(ROOT, "..", "server", "data");
export const DEFAULT_PORT = 8766;

function dataDir() {
  return process.env.AGENT_DATA_DIR ? path.resolve(process.env.AGENT_DATA_DIR) : DEFAULT_DATA_DIR;
}

const IS_MOCK = process.env.AGENT_MOCK === "1";

// ---- messaging helpers ------------------------------------------------------

function send(socket, obj) {
  if (socket && socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify(obj));
  }
}

// A short (safe) transcript of prior turns, used to carry context when a fresh
// session is created (e.g. after a panel reconnect) via the `messages` field.
function serializeMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0) return "";
  const take = messages.slice(-40);
  const parts = [];
  for (const m of take) {
    const role = (m && m.role) || "";
    let content = m && m.content;
    if (Array.isArray(content)) {
      content = content
        .filter((c) => c && c.type === "text")
        .map((c) => c.text)
        .join(" ");
    }
    if (typeof content === "string" && content.trim()) {
      parts.push(`${role === "assistant" ? "Assistant" : role === "user" ? "User" : role}: ${content.trim()}`);
    }
  }
  return parts.length ? `\n\nPrior conversation so far:\n${parts.join("\n")}` : "";
}

// ---- mock inference (AGENT_MOCK=1) -----------------------------------------

// A tiny "assistant" that streams a deterministic answer and settles, so the
// service + panel protocol is verifiable without an OpenRouter key.
function buildMockAnswer(prompt, tree) {
  const links = [];
  const walk = (n) => {
    for (const l of n.links || []) links.push(l);
    for (const c of n.children || []) walk(c);
  };
  walk(tree || {});
  const urlLine = links.length > 0 ? `\n\nRelevant urls in the capture: ${links[0]}` : "";
  const lines = [
    "This is a stubbed agent answer (AGENT_MOCK=1; no OpenRouter call was made).\n",
    `Your question: "${prompt}".`,
    `The capture contains ${(tree && tree.tweet_text) ? "tweet text" : "a tweet"}${links.length ? ` and ${links.length} link(s)` : ""}.`,
    urlLine,
    "\nA real run would reason over the capture and its urls with the fetch_url tool.",
  ];
  return lines.join("\n");
}

class MockHandle {
  constructor({ captureId, socket, dataDir, model }) {
    this.captureId = captureId;
    this.socket = socket;
    this.dataDir = dataDir;
    this.model = model;
    this.turns = [];
    this.sessionId = newSessionId();
    this.timers = [];
  }
  run(msg) {
    const { prompt, tree } = msg;
    const answer = buildMockAnswer(prompt, tree);
    this.turns.push({ role: "user", content: prompt });
    const chunks = answer.match(/.{1,40}/gs) || [];
    chunks.forEach((chunk, i) => {
      this.timers.push(
        setTimeout(() => {
          send(this.socket, { type: "delta", captureId: this.captureId, text: chunk });
        }, 30 * (i + 1))
      );
    });
    const settledAt = 60 + 30 * chunks.length;
    this.timers.push(
      setTimeout(() => {
        this.turns.push({ role: "assistant", content: answer });
        const { sessionId, sessionFile } = persistSession(
          this.dataDir,
          this.sessionId,
          this.turns.slice()
        );
        send(this.socket, {
          type: "settled",
          captureId: this.captureId,
          sessionId,
          sessionFile,
          model: this.model,
          cost: 0,
        });
      }, settledAt)
    );
  }
  abort() {
    for (const t of this.timers) clearTimeout(t);
    this.timers = [];
  }
}

// ---- main service ----------------------------------------------------------

class AgentService {
  constructor(options = {}) {
    this.dataDir = options.dataDir || dataDir();
    this.cwd = options.cwd || process.cwd();
    this.handles = new Map(); // captureId -> { agent|mock, socket }
  }

  handleFor(captureId) {
    return this.handles.get(captureId);
  }

  async ask(socket, msg) {
    const { captureId, tree, messages, prompt } = msg;
    let handle = this.handles.get(captureId);

    if (handle && handle.agent && handle.agent.isStreaming) {
      send(socket, { type: "error", captureId, message: "Agent is still answering the previous question. Wait for it to finish." });
      return;
    }

    if (!handle || handle.socket !== socket || (handle.mock === false && !handle.agent)) {
      // Fresh handler for this capture (or a reconnect on a new socket).
      if (handle) this.dispose(false);
      handle = this.createHandle(socket, captureId);
    }

    const question = prompt && prompt.trim() ? prompt.trim() : "Analyse this capture.";
    const prior = serializeMessages(messages || []);

    if (handle.mock) {
      handle.mock.run({ prompt: question, tree: tree || {} });
      return;
    }

    try {
      const agent = handle.agent;
      if (!agent.session) await agent.start();
      handle.socket = socket;
      agent.setHandlers({
        onDelta: (text) => send(socket, { type: "delta", captureId, text }),
        onTool: ({ tool, arg }) => send(socket, { type: "tool", captureId, tool, arg }),
        onSettled: (messagesList) => {
          const { sessionId, sessionFile } = persistSession(this.dataDir, handle.sessionId, messagesList);
          const model = String(agent.model && agent.model.id || (currentModelOf(messagesList) || "unknown"));
          const cost = costOfMessages(messagesList);
          send(socket, {
            type: "settled",
            captureId,
            sessionId,
            sessionFile,
            model,
            cost,
          });
        },
      });
      await agent.ask(tree || {}, question + prior);
    } catch (e) {
      send(socket, { type: "error", captureId, message: `Agent unavailable: ${e && e.message ? e.message : e}` });
      this.dispose(captureId);
    }
  }

  async followUp(socket, msg) {
    const { captureId, prompt } = msg;
    const handle = this.handles.get(captureId);
    if (!handle) {
      send(socket, { type: "error", captureId, message: "No active conversation for this capture. Start with an ask." });
      return;
    }
    if (handle.mock) {
      handle.mock.run({ prompt: prompt || "Continue.", tree: {} });
      return;
    }
    const agent = handle.agent;
    if (agent.isStreaming) {
      send(socket, { type: "error", captureId, message: "Agent is still answering. Wait for it to finish." });
      return;
    }
    try {
      await agent.followUp(prompt || "Continue.");
    } catch (e) {
      send(socket, { type: "error", captureId, message: `Agent unavailable: ${e && e.message ? e.message : e}` });
    }
  }

  async abort(msg) {
    const { captureId } = msg;
    const handle = this.handles.get(captureId);
    if (!handle) return;
    if (handle.mock) {
      handle.mock.abort();
      return;
    }
    try {
      if (handle.agent) await handle.agent.abort();
    } catch {
      /* best-effort */
    }
  }

  createHandle(socket, captureId) {
    const handle = { captureId, socket };
    if (process.env.AGENT_MOCK === "1") {
      handle.mock = new MockHandle({
        captureId,
        socket,
        dataDir: this.dataDir,
        model: process.env.AGENT_MODEL || "deepseek/deepseek-v4-flash",
      });
      handle.sessionId = handle.mock.sessionId;
      this.handles.set(captureId, handle);
      return handle;
    }
    handle.agent = new CaptureAgent({ cwd: this.cwd });
    handle.sessionId = newSessionId();
    this.handles.set(captureId, handle);
    return handle;
  }

  dispose(captureId) {
    const handle = this.handles.get(captureId);
    if (!handle) return;
    if (handle.agent) handle.agent.dispose();
    if (handle.mock) handle.mock.abort();
    this.handles.delete(captureId);
  }

  disposeForSocket(socket) {
    for (const [id, handle] of this.handles) {
      if (handle.socket === socket) {
        const hadAgent = !!handle.agent;
        if (hadAgent) handle.agent.dispose();
        if (handle.mock) handle.mock.abort();
        this.handles.delete(id);
      }
    }
  }
}

function onMessage(service, ws, raw) {
  let msg;
  try {
    msg = JSON.parse(raw.toString());
  } catch {
    send(ws, { type: "error", captureId: null, message: "Invalid JSON message" });
    return;
  }
  if (!msg || typeof msg.type !== "string") {
    send(ws, { type: "error", captureId: null, message: "Message must have a type" });
    return;
  }
  const { type, captureId } = msg;
  switch (type) {
    case "ask":
      service.ask(ws, msg).catch((e) =>
        send(ws, { type: "error", captureId, message: `ask failed: ${e && e.message ? e.message : e}` })
      );
      break;
    case "follow_up":
      service.followUp(ws, msg).catch((e) =>
        send(ws, { type: "error", captureId, message: `follow_up failed: ${e && e.message ? e.message : e}` })
      );
      break;
    case "abort":
      service.abort(msg).catch(() => {});
      break;
    default:
      send(ws, { type: "error", captureId, message: `Unknown message type: ${type}` });
  }
}

export function startServer(options = {}) {
  const port = options.port || Number(process.env.AGENT_PORT) || DEFAULT_PORT;
  const service = new AgentService(options);

  const httpServer = http.createServer((_req, res) => {
    res.writeHead(200, { "Content-Type": "text/plain" });
    res.end("capture agent service");
  });

  const wss = new WebSocketServer({ server: httpServer, path: options.path || "/" });

  wss.on("connection", (ws) => {
    send(ws, { type: "ready" });
    ws.on("message", (raw) => onMessage(service, ws, raw));
    ws.on("close", () => service.disposeForSocket(ws));
    ws.on("error", () => service.disposeForSocket(ws));
  });

  httpServer.listen(port, "127.0.0.1", () => {
    console.log(`>> capture agent service on ws://127.0.0.1:${port} (${IS_MOCK ? "MOCK mode" : "real mode"})`);
    console.log(`>> evidence dir: ${service.dataDir}`);
    if (!IS_MOCK && !process.env.OPENROUTER_API_KEY) {
      console.log(">> WARNING: OPENROUTER_API_KEY not set — asks will report 'agent unavailable'.");
    }
  });

  return { httpServer, wss, service };
}

// Allow a direct `node server.js` start (and keep the module importable for tests).
if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  startServer();
}

// Real (pi SDK) agent runner for the capture agent service.
//
// Creates an in-memory AgentSession with exactly one custom tool (fetch_url),
// no coding tools (Decision 03), reasons over the pending capture, streams
// text deltas / tool activity, and on settle hands the full message list back
// so the service can persist it as evidence.

import {
  createAgentSession,
  createExtensionRuntime,
  SessionManager,
  SettingsManager,
} from "@earendil-works/pi-coding-agent";
import { createModelStack, resolveModel } from "./models.mjs";
import { fetchUrlTool } from "./tools/fetch_url.js";
import { serializeTree } from "./serialize.js";

export function makeSystemPrompt() {
  return `You are a research assistant embedded in the Capture instrument. You help the user think about a captured X/Twitter post and the content it links to.

Rules:
- Reason only over the pending capture and the urls inside it.
- When a url in the capture is relevant to the user's question, fetch and read it with the fetch_url tool. You decide which urls matter.
- Use the tool as part of your reasoning, then answer the user's question plainly.
- Be concise and specific. Cite what you actually read; if content is unavailable, say so.
- Never invent, edit, or fabricate content.`;
}

// A fully controlled resource loader: no project/global extensions, skills,
// prompt templates, themes, or context files leak in. Only fetch_url is
// available to the model.
function minimalResourceLoader() {
  return {
    getExtensions: () => ({ extensions: [], errors: [], runtime: createExtensionRuntime() }),
    getSkills: () => ({ skills: [], diagnostics: [] }),
    getPrompts: () => ({ prompts: [], diagnostics: [] }),
    getThemes: () => ({ themes: [], diagnostics: [] }),
    getAgentsFiles: () => ({ agentsFiles: [] }),
    getSystemPrompt: () => makeSystemPrompt(),
    getAppendSystemPrompt: () => [],
    extendResources: () => {},
    reload: async () => {},
  };
}

export class CaptureAgent {
  constructor({ cwd }) {
    this.cwd = cwd || process.cwd();
    this.session = null;
    this.model = null;
    this.handlers = {};
    this.unsub = null;
  }

  get isStreaming() {
    return !!(this.session && this.session.isStreaming);
  }

  async start() {
    const { authStorage, modelRegistry } = createModelStack();
    const model = resolveModel(modelRegistry); // throws if the model is unavailable
    const settingsManager = SettingsManager.inMemory({ compaction: { enabled: false } });
    const { session } = await createAgentSession({
      cwd: this.cwd,
      model,
      thinkingLevel: "medium",
      authStorage,
      modelRegistry,
      settingsManager,
      resourceLoader: minimalResourceLoader(),
      tools: ["fetch_url"],
      customTools: [fetchUrlTool],
      sessionManager: SessionManager.inMemory(this.cwd),
    });
    this.session = session;
    this.model = model;
    this.handlers = {};
    this.unsub = session.subscribe((event) => this._onEvent(event));
    return { model };
  }

  setHandlers(handlers) {
    this.handlers = handlers || {};
  }

  _onEvent(event) {
    if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
      if (this.handlers.onDelta) this.handlers.onDelta(event.assistantMessageEvent.delta);
    } else if (event.type === "tool_execution_start") {
      if (this.handlers.onTool) {
        this.handlers.onTool({ tool: event.toolName, arg: event.args && event.args.url });
      }
    } else if (event.type === "agent_end") {
      if (this.handlers.onSettled) this.handlers.onSettled(event.messages || []);
    } else if (event.type === "message_end" && this.handlers.onMessageEnd) {
      // reserved
    }
  }

  // First turn: inject the serialized tree (context) then the user's question.
  async ask(tree, prompt) {
    const context = serializeTree(tree || {});
    const userText = prompt && prompt.trim() ? prompt.trim() : "Analyse this capture.";
    await this.session.prompt(`${context}\n\nQuestion: ${userText}`);
  }

  // Follow-up in the same conversation; the session retains capture context.
  async followUp(prompt) {
    await this.session.followUp(prompt && prompt.trim() ? prompt.trim() : "Continue.");
  }

  async abort() {
    if (this.session) await this.session.abort();
  }

  dispose() {
    if (this.unsub) this.unsub();
    if (this.session) this.session.dispose();
    this.session = null;
    this.unsub = null;
  }
}

// Model stack for the capture agent service (Decision 02).
//
// Inference runs through OpenRouter via pi's ModelRuntime. The API key lives
// ONLY in this service's environment (OPENROUTER_API_KEY) — never in the
// browser. Default model deepseek/deepseek-v4-flash (thinking on), overridable
// with AGENT_MODEL.
//
// Auth + registry are in-memory: nothing sensitive is ever written to disk on
// the host, and the repo stays free of stray credential/registry files. The
// openrouter model is resolved from pi's built-in model registry.

import { AuthStorage, ModelRegistry } from "@earendil-works/pi-coding-agent";

export const DEFAULT_MODEL = "deepseek/deepseek-v4-flash";

// Design note on temperature: pi's session API does not expose a per-session
// temperature knob to SDK callers for reasoning models (temperature lives on
// provider StreamOptions that pi controls internally). The PRD's "~0.2" is
// honoured as documented intent; pi manages temperature for reasoning models
// itself. See outbox decisions.

export function createModelStack() {
  const authStorage = AuthStorage.inMemory();
  if (process.env.OPENROUTER_API_KEY) {
    authStorage.setRuntimeApiKey("openrouter", process.env.OPENROUTER_API_KEY);
  }
  const modelRegistry = ModelRegistry.inMemory(authStorage);
  return { authStorage, modelRegistry };
}

export function resolveModel(modelRegistry) {
  const id = process.env.AGENT_MODEL || DEFAULT_MODEL;
  const model = modelRegistry.find("openrouter", id);
  if (!model) {
    throw new Error(`Model not found on provider "openrouter": ${id}`);
  }
  return model;
}

// Persistence of agent conversations as pi-native session evidence (Decision 04).
//
// One artefact = one capture tree line with an `agent` envelope, and the full
// conversation written verbatim to `data/sessions/<uuid>/session.jsonl` in pi's
// native v3 session format — the same format the factory knowledge base stores
// and `extract-context` understands. Answers are saved verbatim, never edited.

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

export function newSessionId() {
  return crypto.randomUUID();
}

export function newEntryId() {
  return crypto.randomBytes(4).toString("hex");
}

// Sum the reported cost across assistant messages (usage.cost.total). Returns 0
// when usage data is absent (e.g. a stubbed run).
export function costOfMessages(messages) {
  let total = 0;
  for (const msg of messages || []) {
    const cost = msg && msg.usage && msg.usage.cost;
    if (cost && typeof cost.total === "number") total += cost.total;
  }
  return total;
}

export function currentModelOf(messages, fallback) {
  for (const msg of messages || []) {
    if (msg && msg.role === "assistant" && msg.model) return msg.model;
  }
  return fallback || "";
}

// Serialize a list of AgentMessages into a pi-native v3 session.jsonl string.
// First line is the session header; each subsequent line is a `message` entry
// linked by id/parentId into a linear tree (the path pi walks to rebuild the
// context window).
export function serializeSession(messages, { sessionId, cwd }) {
  const header = {
    type: "session",
    version: 3,
    id: sessionId,
    timestamp: new Date().toISOString(),
    cwd: cwd || process.cwd(),
  };
  const lines = [JSON.stringify(header)];
  let parentId = null;
  for (const msg of messages || []) {
    const id = newEntryId();
    const timestamp = new Date(
      typeof msg.timestamp === "number" ? msg.timestamp : Date.now()
    ).toISOString();
    const entry = { type: "message", id, parentId, timestamp, message: msg };
    lines.push(JSON.stringify(entry));
    parentId = id;
  }
  return lines.join("\n") + "\n";
}

// Persist messages to data/sessions/<sessionId>/session.jsonl. Returns the
// envelope fragments the capture server accepts.
export function persistSession(dataDir, sessionId, messages) {
  const dir = path.join(dataDir, "sessions", sessionId);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, "session.jsonl");
  fs.writeFileSync(file, serializeSession(messages, { sessionId }), "utf8");
  return {
    sessionId,
    sessionFile: path.join("sessions", sessionId, "session.jsonl").split(path.sep).join("/"),
  };
}

// Serialize a capture tree into a compact text block that is injected inline
// into the agent's first prompt. This is the "context injection" seam: the
// root tweet plus curated comment nodes (text + urls) become the raw material
// the agent reasons over.

function nodeToText(node, depth, lines) {
  const pad = "  ".repeat(depth);
  const author = node.author ? `${node.author}` : "unknown author";
  const text = node.tweet_text && node.tweet_text.trim() ? node.tweet_text.trim() : "(no text)";
  lines.push(`${pad}- ${author}: ${text}`);
  if (Array.isArray(node.links) && node.links.length) {
    for (const link of node.links) {
      lines.push(`${pad}  url: ${link}`);
    }
  }
  if (node.tweet_url) {
    lines.push(`${pad}  source: ${node.tweet_url}`);
  }
  if (node.notes && node.notes.trim()) {
    lines.push(`${pad}  notes: ${node.notes.trim()}`);
  }
  for (const child of node.children || []) {
    nodeToText(child, depth + 1, lines);
  }
}

export function serializeTree(tree) {
  const lines = [];
  lines.push("Here is the pending capture you are being asked about:");
  nodeToText(tree || {}, 0, lines);
  return lines.join("\n");
}

// fetch_url custom tool for the capture agent.
//
// The ONLY tool the agent gets in v1 (Decision 03): fetch-and-read a url,
// server-side so there is no browser CORS. Bounded with hard caps (body size,
// timeout) so one huge page cannot stall a session. The agent decides which of
// the capture's urls to fetch.

import { defineTool } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

export const MAX_BODY_BYTES = 1024 * 1024; // ~1 MB response body cap
export const TIMEOUT_MS = 30_000; // 30 s overall cap

// Strip markup so the model reads prose, not HTML soup. Kept deliberately
// lightweight — not a full HTML parser.
function htmlToText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

// Fetch a url with caps using the runtime's global fetch (handles redirects).
// Returns { ok, text } — text is always a string the model can read.
export async function fetchWithCaps(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, text: `fetch_url: invalid URL: ${url}` };
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    return { ok: false, text: `fetch_url: unsupported protocol "${parsed.protocol}" (only http/https)` };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

  let res;
  try {
    res = await fetch(parsed.href, {
      signal: controller.signal,
      redirect: "follow",
      headers: {
        "user-agent": "capture-agent-service/0.1 (local reasoning agent)",
        accept: "text/html,text/plain;q=0.9,*/*;q=0.8",
      },
    });
  } catch (e) {
    clearTimeout(timer);
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "unknown fetch error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }

  if (!res.ok) {
    clearTimeout(timer);
    if (res.body && res.body.cancel) await res.body.cancel().catch(() => {});
    return { ok: false, text: `fetch_url: HTTP ${res.status} for ${url}` };
  }

  const contentType = String(res.headers.get("content-type") || "").toLowerCase();
  const declaredLength = parseInt(String(res.headers.get("content-length") || "0"), 10);
  if (declaredLength > MAX_BODY_BYTES) {
    clearTimeout(timer);
    if (res.body && res.body.cancel) await res.body.cancel().catch(() => {});
    return { ok: false, text: `fetch_url: response too large (${declaredLength} bytes > 1 MB cap)` };
  }

  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  let tooLarge = false;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.length;
      if (total > MAX_BODY_BYTES) {
        tooLarge = true;
        break;
      }
      chunks.push(value);
    }
  } catch (e) {
    clearTimeout(timer);
    if (tooLarge) {
      return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
    }
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "read error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }
  clearTimeout(timer);
  if (tooLarge) {
    await reader.cancel().catch(() => {});
    return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
  }

  let bodyText;
  try {
    bodyText = Buffer.concat(chunks).toString("utf8");
  } catch {
    bodyText = "";
  }
  const isHtml = contentType.includes("html");
  const text = (isHtml ? htmlToText(bodyText) : bodyText).trim();
  if (!text) {
    return { ok: false, text: `fetch_url: no readable text content at ${url}` };
  }
  return { ok: true, text };
}

export const fetchUrlTool = defineTool({
  name: "fetch_url",
  label: "Fetch URL",
  description:
    "Fetch and read the text content of a URL (HTML or plain text). Runs server-side, body capped at ~1 MB and 30s timeout. Use only for urls present in the capture being analyzed.",
  parameters: Type.Object({
    url: Type.String({ description: "The http(s) URL to fetch and read." }),
  }),
  execute: async (_toolCallId, params) => {
    const { ok, text } = await fetchWithCaps(params.url);
    return {
      content: [{ type: "text", text }],
      details: { ok, url: params.url },
    };
  },
});

{
  "name": "capture-agent-service",
  "version": "0.1.0",
  "private": true,
  "description": "Local pi-agent reasoning service for the Capture instrument. Exposes a WebSocket on 127.0.0.1:8766 that reasons over a pending capture and persists pi-native session evidence.",
  "type": "module",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node server.js",
    "smoke": "node test/smoke.mjs"
  },
  "dependencies": {
    "@earendil-works/pi-coding-agent": "^0.74.2",
    "ws": "^8.18.0"
