// Side panel logic for Capture.
// Renders the in-progress capture as a live view: the root tweet plus any
// curated comments nested in an indented tree. Re-renders live when the
// content script adds/removes comments (via background broadcast). On Save it
// POSTs the whole recursive tree to the local server.

(() => {
  "use strict";

  const statusEl = document.getElementById("status");
  const contentEl = document.getElementById("content");
  const authorEl = document.getElementById("author");
  const urlEl = document.getElementById("tweet-url");
  const scrapeWarnEl = document.getElementById("scrape-warning");
  const textEl = document.getElementById("tweet-text");
  const linksEl = document.getElementById("links");
  const notesEl = document.getElementById("notes");
  const contextFieldset = document.getElementById("context-fieldset");
  const contextLegend = document.getElementById("context-legend");
  const contextTree = document.getElementById("context-tree");
  const saveBtn = document.getElementById("save");

  // Ask panel (agent)
  const agentFieldset = document.getElementById("agent-fieldset");
  const agentThread = document.getElementById("agent-thread");
  const agentStatus = document.getElementById("agent-status");
  const agentInput = document.getElementById("agent-input");
  const agentAskBtn = document.getElementById("agent-ask");
  const agentAbortBtn = document.getElementById("agent-abort");
  const agentUnavailable = document.getElementById("agent-unavailable");

  let agentUrl = "ws://127.0.0.1:8766";
  let agentBusy = false;
  let agentEnvelope = null; // stashed when the agent settles (attached on Save)
  let agentEverAvail = false;
  let agentPending = null; // { tree, prompt } waiting for a connection
  let agentMessages = []; // { role, content } transcript for reconnection context
  let agentClient = null;

  let serverUrl = "http://127.0.0.1:8765/api/capture";
  let current = null; // the root node of the in-progress capture (has children[])

  function setStatus(msg, kind) {
    statusEl.textContent = "";
    statusEl.className = "status " + (kind || "pending");
    statusEl.innerHTML = msg;
  }

  function clearStatus() {
    statusEl.textContent = "";
    statusEl.className = "";
  }

  function renderLinks(list) {
    linksEl.innerHTML = "";
    const arr = Array.isArray(list) ? list : [];
    if (arr.length === 0) {
      const li = document.createElement("li");
      li.className = "empty";
      li.textContent = "No links found.";
      linksEl.appendChild(li);
      return;
    }
    for (const link of arr) {
      const li = document.createElement("li");
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = link;
      cb.checked = true;
      const label = document.createElement("label");
      label.textContent = link;
      li.appendChild(cb);
      li.appendChild(label);
      linksEl.appendChild(li);
    }
  }

  // Build one comment node row, indented by depth. Comment links are shown
  // plainly (captured automatically; no per-node toggles in v1).
  function nodeEl(node, depth) {
    const div = document.createElement("div");
    div.className = "cnode";
    div.style.paddingLeft = 6 + depth * 16 + "px";

    if (node.author) {
      const a = document.createElement("div");
      a.className = "c-author";
      a.textContent = node.author;
      div.appendChild(a);
    }
    const t = document.createElement("div");
    t.className = "c-text";
    t.textContent = node.tweet_text || "(no text scraped)";
    div.appendChild(t);
    if (node.tweet_url) {
      const u = document.createElement("span");
      u.className = "c-url";
      u.textContent = node.tweet_url;
      div.appendChild(u);
    }
    if (Array.isArray(node.links) && node.links.length) {
      const ul = document.createElement("ul");
      for (const link of node.links) {
        const li = document.createElement("li");
        li.textContent = link;
        ul.appendChild(li);
      }
      div.appendChild(ul);
    }
    return div;
  }

  function renderChildren(parentNode, depth, container) {
    for (const child of parentNode.children || []) {
      container.appendChild(nodeEl(child, depth));
      renderChildren(child, depth + 1, container);
    }
  }

  // Re-render the Context (comments tree) section only — called on live
  // updates so notes/text edits in the panel aren't clobbered.
  function renderContext() {
    const kids = (current && current.children) || [];
    contextFieldset.style.display = kids.length ? "block" : "none";
    contextLegend.textContent = "Context (" + kids.length + ")";
    contextTree.innerHTML = "";
    if (kids.length) renderChildren(current, 1, contextTree);
  }

  function renderRoot() {
    const node = current || {};
    authorEl.textContent = node.author || "Unknown author";
    urlEl.textContent = node.tweet_url || "";
    textEl.value = node.tweet_text || "";
    if (!node.tweet_text && !node.tweet_url) {
      scrapeWarnEl.style.display = "block";
    } else {
      scrapeWarnEl.style.display = "none";
    }
    renderLinks(node.links || []);
  }

  function render(data) {
    current = data || { tweet_url: "", author: "", tweet_text: "", links: [], parent_url: null, notes: "", children: [] };
    renderRoot();
    renderContext();
    notesEl.value = current.notes || "";
    contentEl.style.display = "block";
    clearStatus();
    resetAgentForNewCapture();
  }

  // Deep-clone current into a tree, apply panel edits (root text, notes,
  // checked root links), and return it for submission.
  function collectArtefact() {
    const tree = JSON.parse(JSON.stringify(current || {}));
    tree.tweet_text = textEl.value.trim();
    tree.notes = notesEl.value.trim();
    const checkedLinks = [];
    for (const li of linksEl.querySelectorAll("li")) {
      const cb = li.querySelector('input[type="checkbox"]');
      if (cb && cb.checked && cb.value) checkedLinks.push(cb.value);
    }
    tree.links = checkedLinks;
    return tree;
  }

  async function submit() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to save — no tweet URL.", "error");
      return;
    }
    const artefact = collectArtefact();
    if (agentEnvelope) artefact.agent = agentEnvelope; // link the saved evidence
    saveBtn.disabled = true;
    setStatus("Saving…", "pending");
    try {
      const resp = await fetch(serverUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(artefact),
      });
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const body = await resp.json();
      setStatus(
        "Saved ✓ " + (body.captured_at ? "at " + body.captured_at : ""),
        "ok"
      );
      chrome.runtime.sendMessage({ type: "clear-pending-capture" });
      saveBtn.disabled = false;
    } catch (e) {
      setStatus(
        "<strong>Server offline</strong> — restart and try again. Your data is still here.",
        "error"
      );
      saveBtn.disabled = false;
    }
  }

  saveBtn.addEventListener("click", submit);

  // ------------------------------------------------------------------------
  // Agent (Ask) — stories 1-5
  // ------------------------------------------------------------------------

  function setAgentStatus(msg, kind) {
    if (!msg) {
      agentStatus.style.display = "none";
      agentStatus.className = "status";
      agentStatus.textContent = "";
      return;
    }
    agentStatus.style.display = "block";
    agentStatus.className = "status " + (kind || "pending");
    agentStatus.textContent = msg;
  }

  function showAgentUnavailable() {
    agentUnavailable.style.display = "block";
    agentFieldset.style.opacity = "0.75";
  }

  function hideAgentUnavailable() {
    agentUnavailable.style.display = "none";
    agentFieldset.style.opacity = "";
  }

  function addAgentBubble(cls, text) {
    const div = document.createElement("div");
    div.className = "agent-msg " + cls;
    div.textContent = text || "";
    agentThread.appendChild(div);
    return div;
  }

  function updateAgentControls() {
    agentAskBtn.disabled = agentBusy || !!(current && current.tweet_url) === false;
    agentAbortBtn.style.display = agentBusy ? "inline-block" : "none";
    agentAskBtn.style.display = agentBusy ? "none" : "inline-block";
  }

  function captureId() {
    return current && current.tweet_url ? "capture:" + current.tweet_url : "capture:active";
  }

  function appendDeliveredText(text) {
    if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
    currentAssistantBubble.textContent += text;
    currentAssistantText += text;
    agentThread.scrollTop = agentThread.scrollHeight;
  }

  function flushPendingIfConnected() {
    if (agentPending && agentClient && agentClientWasOpen()) {
      agentClient.ask(agentPending.captureId, agentPending.tree, agentPending.prompt, agentPending.messages);
      agentPending = null;
    }
  }

  function agentClientWasOpen() {
    return agentClient && agentClient.ws && agentClient.ws.readyState === WebSocket.OPEN;
  }

  function initAgentClient() {
    if (agentClient) return;
    agentClient = new AgentClient({
      url: agentUrl,
      handlers: {
        onReady: () => {
          agentEverAvail = true;
          hideAgentUnavailable();
          setAgentStatus("Connected.", "ok");
          setTimeout(() => setAgentStatus(null), 1200);
          flushPendingIfConnected();
        },
        onDelta: (msg) => {
          if (msg.captureId !== captureId()) return;
          appendDeliveredText(msg.text);
        },
        onTool: (msg) => {
          if (msg.captureId !== captureId()) return;
          addAgentBubble("tool", "⚙ fetched " + (msg.arg || msg.tool));
        },
        onSettled: (msg) => {
          if (msg.captureId !== captureId()) return;
          // finalize assistant bubble, stash the envelope for Save
          if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
          if (msg.model) {
            const meta = document.createElement("div");
            meta.className = "muted";
            meta.style.cssText = "margin-top:4px;font-size:11px;";
            meta.textContent = "model " + msg.model + (typeof msg.cost === "number" ? " · $" + msg.cost.toFixed(5) : "");
            currentAssistantBubble.appendChild(meta);
          }
          currentAssistantBubble = null;
          agentEnvelope = {
            sessionId: msg.sessionId,
            sessionFile: msg.sessionFile,
            prompt: lastAgentPrompt || "",
            model: msg.model || "",
            capturedAt: new Date().toISOString(),
            cost: typeof msg.cost === "number" ? msg.cost : undefined,
          };
          agentMessages.push({ role: "assistant", content: currentAssistantText });
          currentAssistantText = "";
          agentBusy = false;
          updateAgentControls();
          setAgentStatus("Answer saved with this capture.", "ok");
          setTimeout(() => setAgentStatus(null), 1500);
        },
        onError: (msg) => {
          agentBusy = false;
          updateAgentControls();
          if (msg && /unreachable|unavailable/i.test(msg.message || "")) {
            showAgentUnavailable();
            setAgentStatus("Agent unavailable. You can still save.", "error");
          } else {
            setAgentStatus("Agent error: " + ((msg && msg.message) || "unknown"), "error");
          }
        },
        onDown: (msg) => {
          // service is not up yet — show the unavailable state, keep retrying
          showAgentUnavailable();
          setAgentStatus("Agent unavailable. You can still save.", "error");
        },
      },
    });
    agentClient.connect();
  }

  let currentAssistantBubble = null;
  let currentAssistantText = "";
  let lastAgentPrompt = "";

  function askAgent() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to ask about — no tweet URL.", "error");
      return;
    }
    const prompt = agentInput.value.trim();
    if (!prompt) return;
    if (agentBusy) return;

    const tree = collectArtefact();
    lastAgentPrompt = prompt;
    addAgentBubble("user", prompt);
    agentMessages.push({ role: "user", content: prompt });
    agentInput.value = "";
    currentAssistantBubble = null;
    currentAssistantText = "";
    agentBusy = true;
    updateAgentControls();
    hideAgentUnavailable();

    if (agentClientWasOpen()) {
      agentClient.ask(captureId(), tree, prompt, []);
    } else {
      agentPending = { captureId: captureId(), tree, prompt, messages: agentMessages.slice() };
      setAgentStatus("Connecting to agent service…", "pending");
      initAgentClient();
    }
  }

  function followUpAgent() {
    if (agentBusy) return;
    const prompt = agentInput.value.trim();
    if (!prompt) return;
    if (!agentEverAvail) {
      askAgent();
      return;
    }
    lastAgentPrompt = prompt;
    addAgentBubble("user", prompt);
    agentMessages.push({ role: "user", content: prompt });
    agentInput.value = "";
    currentAssistantBubble = null;
    currentAssistantText = "";
    agentBusy = true;
    updateAgentControls();
    if (agentClientWasOpen()) {
      agentClient.followUp(captureId(), prompt);
    } else {
      agentPending = { captureId: captureId(), tree: collectArtefact(), prompt, messages: agentMessages.slice() };
      setAgentStatus("Reconnecting to agent service…", "pending");
      initAgentClient();
    }
  }

  agentInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (agentEverAvail) followUpAgent();
      else askAgent();
    }
  });
  agentAskBtn.addEventListener("click", askAgent);
  agentAbortBtn.addEventListener("click", () => {
    if (agentClient) agentClient.abort(captureId());
    agentBusy = false;
    currentAssistantBubble = null;
    currentAssistantText = "";
    updateAgentControls();
    setAgentStatus("Stopped.", "pending");
  });

  function resetAgentForNewCapture() {
    agentEnvelope = null;
    agentMessages = [];
    lastAgentPrompt = "";
    currentAssistantBubble = null;
    agentBusy = false;
    agentThread.innerHTML = "";
    updateAgentControls();
    if (agentEverAvail) hideAgentUnavailable();
    else if (agentClient) showAgentUnavailable();
  }

  // Live updates from the background (content added/removed a comment).
  chrome.runtime.onMessage.addListener((message) => {
    if (!message) return;
    if (message.type === "capture-updated") {
      chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
        if (chrome.runtime.lastError || !resp || !resp.data) return;
        current = resp.data;
        renderContext(); // refresh tree only; keep notes/text edits
      });
    } else if (message.type === "capture-cleared") {
      // Capture completed — reset the panel to the empty prompt.
      current = null;
      currentAssistantBubble = null;
      contentEl.style.display = "none";
      resetAgentForNewCapture();
      setStatus("Capture complete. Hover a tweet on X and click <strong>Capture</strong> to start again.", "ok");
    }
  });

  // Ask background for the pending capture (survives page navigation).
  chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
    if (chrome.runtime.lastError) {
      setStatus("Background unavailable. Reopen the panel.", "error");
      return;
    }
    if (resp && resp.serverUrl) serverUrl = resp.serverUrl;
    if (resp && resp.data) {
      render(resp.data);
    } else {
      contentEl.style.display = "none";
      setStatus("No pending capture. Hover a tweet on X and click <strong>Capture</strong>.", "pending");
    }
  });
})();

// Smoke test for the capture agent service protocol.
//
// Connects to a running service (default ws://127.0.0.1:8766), sends an `ask`,
// then a `follow_up`, and asserts the protocol contract: deltas arrive, a
// `settled` event returns a sessionId + sessionFile, and the session evidence
// file exists on disk. Designed to run against AGENT_MOCK=1 (no OpenRouter key
// needed) — see package.json "smoke" script.
//
// Usage:  node test/smoke.mjs [ws-url]

import WebSocket from "ws";
import fs from "node:fs";
import path from "node:path";

const url = process.argv[2] || "ws://127.0.0.1:8766";
const dataDir = process.env.AGENT_DATA_DIR || path.resolve(process.cwd(), "..", "server", "data");

const captureId = "smoke-c1";
const tree = {
  tweet_url: "https://x.com/user/status/123",
  author: "@user",
  tweet_text: "A tweet about arxiv and open source.",
  links: ["https://arxiv.org/abs/1234"],
  parent_url: null,
  notes: "",
  children: [],
};

const ws = new WebSocket(url);
const events = [];
let settled = null;
let deltas = 0;
let settledCount = 0;

function fail(msg) {
  console.error("SMOKE FAIL:", msg);
  process.exit(1);
}

const timeout = setTimeout(() => fail(`timed out waiting for settled (events: ${events.join(",")})`), 20000);

ws.on("open", () => {
  ws.send(JSON.stringify({ type: "ask", captureId, tree, prompt: "Summarise this post and its core claim." }));
});

ws.on("message", (raw) => {
  const msg = JSON.parse(raw.toString());
  events.push(msg.type);
  if (msg.type === "delta" && msg.captureId === captureId) deltas += 1;
  if (msg.type === "error") fail(`service error: ${msg.message}`);
  if (msg.type === "settled" && msg.captureId === captureId) {
    settled = msg;
    settledCount += 1;
    // verify evidence file exists
    const file = path.resolve(dataDir, msg.sessionFile);
    console.log(`>> settled: sessionId=${msg.sessionId} sessionFile=${msg.sessionFile} model=${msg.model} cost=${msg.cost}`);
    if (!fs.existsSync(file)) fail(`session evidence file not found: ${file}`);
    const content = fs.readFileSync(file, "utf8");
    const lines = content.trim().split("\n");
    if (!lines[0] || !lines[0].includes('"type":"session"')) fail("session file missing header");
    if (deltas === 0) fail("expected at least one delta before settled");
    // follow up on same conversation
    ws.send(JSON.stringify({ type: "follow_up", captureId, prompt: "What would you fetch to verify the claim?" }));
  }
  if (settled && msg.type === "settled" && msg.captureId === captureId && settledCount === 2) {
    // second settled (follow-up turn) confirms context reuse across turns
    clearTimeout(timeout);
    console.log("SMOKE PASS: ask -> deltas -> settled -> follow_up -> settled; evidence persisted.");
    process.exit(0);
  }
});

ws.on("error", (e) => fail(`websocket error: ${e && e.message}`));

// Unit tests for the fetch_url tool caps (size / timeout / protocol).
//
// Run:  node test/fetch_url.test.mjs
import http from "node:http";
import assert from "node:assert";
import { fetchWithCaps, MAX_BODY_BYTES } from "../tools/fetch_url.js";

async function main() {
  // invalid url -> error text, ok:false
  let r = await fetchWithCaps("not a url");
  assert.strictEqual(r.ok, false);
  assert.match(r.text, /invalid url/i);

  // unsupported protocol -> error text
  r = await fetchWithCaps("file:///etc/passwd");
  assert.strictEqual(r.ok, false);
  assert.match(r.text, /unsupported protocol/i);

  // simple local server returning text
  const server = http.createServer((req, res) => {
    res.writeHead(200, { "Content-Type": "text/plain" });
    res.end("hello from capture test server");
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = server.address().port;

  r = await fetchWithCaps(`http://127.0.0.1:${port}/ok`);
  assert.strictEqual(r.ok, true);
  assert.match(r.text, /hello from capture test server/);

  // html page -> stripped to text
  const htmlServer = http.createServer((req, res) => {
    res.writeHead(200, { "Content-Type": "text/html" });
    res.end("<html><head><style>a{}</style><script>var x=1;</script></head><body><h1>Title</h1><p>Some <b>body</b> text.</p></body></html>");
  });
  await new Promise((resolve) => htmlServer.listen(0, "127.0.0.1", resolve));
  const htmlPort = htmlServer.address().port;
  r = await fetchWithCaps(`http://127.0.0.1:${htmlPort}/page`);
  assert.strictEqual(r.ok, true);
  assert.match(r.text, /Title/);
  assert.match(r.text, /body text/);
  assert.doesNotMatch(r.text, /<script/);

  // body cap -> too-large error
  const bigServer = http.createServer((req, res) => {
    res.writeHead(200, { "Content-Type": "text/plain" });
    const big = "x".repeat(MAX_BODY_BYTES + 100 * 1024);
    res.write(big.slice(0, 4096));
    // keep the body open long enough to exceed the cap
    const interval = setInterval(() => {
      try {
        res.write(big.slice(0, 16384));
      } catch {
        clearInterval(interval);
      }
    }, 5);
    req.on("close", () => clearInterval(interval));
  });
  await new Promise((resolve) => bigServer.listen(0, "127.0.0.1", resolve));
  const bigPort = bigServer.address().port;
  r = await fetchWithCaps(`http://127.0.0.1:${bigPort}/big`);
  assert.strictEqual(r.ok, false);
  assert.match(r.text, /cap|too large/i);

  server.close();
  htmlServer.close();
  bigServer.close();
  console.log("fetch_url caps: PASS (invalid url, protocol, plain text, html strip, body cap)");
}

