def append_artefact(artefact: dict, path: Path | None = None) -> None:
    """Append one artefact as a JSON line, write + flush. Returns None."""
    target = path if path is not None else data_path()
    with target.open("a", encoding="utf-8") as f:
        f.write(json.dumps(artefact, ensure_ascii=False) + "\n")
        f.flush()


def validate_node(node, path="root") -> None:
    """Validate a node recursively. Raises ValueError with a descriptive
    message on the first problem found. Every nested child must have a
    tweet_url."""
    if not isinstance(node, dict):
        raise ValueError(f"{path} must be an object")
    if not node.get("tweet_url"):
        raise ValueError(f"{path} is missing required field 'tweet_url'")
    children = node.get("children") or []
    if not isinstance(children, list):
        raise ValueError(f"{path}.children must be a list")
    for i, child in enumerate(children):
        validate_node(child, f"{path}.children[{i}]")


@app.post("/api/capture")
async def capture(request: Request):
    try:
        body = await request.json()
    except Exception:
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "invalid JSON body"}
        )

    if not isinstance(body, dict):
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "payload must be an object"}
        )

    try:
        validate_node(body)
    except ValueError as exc:
        return JSONResponse(
            status_code=400,
            content={"status": "error", "error": str(exc)},
        )
